let objective,detail;if(view.mode==='campaign'){const mission=getMission(view.missionId),steps=mission.steps,o=steps[view.objective],operation=view.operation,target=operation?.focus||o;$('mission-checklist').hidden=false;$('mission-progress').hidden=false;if(lastObjective!==view.objective){lastObjective=view.objective;$('mission-checklist').innerHTML=steps.map((step,i)=>'<div class="'+(i<view.objective?'complete':i===view.objective?'current':'waiting')+'"><span>'+(i<view.objective?'✓':i+1)+'</span>'+step.short+'</div>').join('')}$('mission-progress-fill').style.width=clamp((view.objective+(o?.duration?(view.radio?.progress||0)/o.duration:operation?.progress||0))/steps.length*100,0,100)+'%';objective=o?.label||'OPERATION COMPLETE';detail=operation?.detail||o?.detail||mission.success;if(o){let distance=Math.hypot(player.x-target.x,player.z-target.z);$('interact').hidden=distance>3.5||Math.abs(player.y)>2||!player.alive||['hunt','destroy'].includes(o.kind);$('interact').textContent=view.radio?.active?'IN PROGRESS — STAY IN THE AREA':'[ E ]  '+o.prompt;if(o.duration&&view.radio?.active)detail=distance<4.5?Math.floor(view.radio.progress/o.duration*100)+'% complete · '+Math.ceil(o.duration-view.radio.progress)+' seconds remaining. Hold this position.':'Objective paused. Return to the marked area to continue.';if(o.kind==='evacuate'&&view.radio?.active)detail='RAVEN ONE IN '+Math.ceil(o.duration-view.radio.progress)+' SECONDS · Defend the landing zone. '+(distance>4.5?'Return to the marker to resume extraction.':'');const v=new T.Vector3(target.x,(target.y||.2)+.8,target.z).project(world.camera);$('waypoint').hidden=v.z>1;if(v.z<=1){$('waypoint').style.left=clamp((v.x*.5+.5)*innerWidth,45,innerWidth-45)+'px';$('waypoint').style.top=clamp((-v.y*.5+.5)*innerHeight,65,innerHeight-100)+'px';$('waypoint').querySelector('span').textContent=Math.round(distance)+' m'}}}else{$('mission-checklist').hidden=true;$('mission-progress').hidden=true;$('waypoint').hidden=true;$('interact').hidden=true;objective=view.mode==='coop'?'HOLD THE TOWN / WAVE '+view.wave:view.mode==='tdm'?'ELIMINATE THE OPPOSING TEAM':'EVERY SOLDIER FOR THEMSELVES';detail=view.mode==='coop'?(view.waveDelay?'Next wave incoming. Resupply and regroup.':view.players.filter(p=>p.bot&&p.alive).length+' hostiles remaining.'):view.mode==='tdm'?'First team to 25 eliminations.':'First player to 15 eliminations.'}if(view.mode==='zombie'){const c=view.survival;objective='SURVIVE TEN DAYS · '+c.phase+' '+c.day+' / 10';detail=view.players.filter(p=>p.role==='zombie'&&p.alive).length+' infected active · '+(c.night?'THERMAL TRACKING ACTIVE · Hold out until dawn.':'Resupply, climb a stair tower, or defend Civic Square.');$('mission-progress').hidden=false;$('mission-progress-fill').style.width=(c.progress*100)+'%'}if($('interact').hidden&&player.alive){const s=nearbySupply(player,view.supplies||[],view.time);if(s){$('interact').hidden=false;$('interact').textContent='[ E ] '+(s.kind==='medical'?'FIELD MEDICINE · RESTORE 60 HEALTH':'AMMUNITION · REFILL RESERVES')}}if(!player.alive){objective='YOU ARE DOWN';detail=mode==='online'?'Redeploying in '+Math.max(0,Math.ceil(player.respawnAt-view.time))+' seconds.':view.mode==='zombie'?'One life. Restart from day one.':'Resume from your checkpoint.'}$('objective-title').textContent=objective;$('objective-detail').textContent=detail;
