function frame(t){requestAnimationFrame(frame);let dt=Math.min(.05,(t-last)/1000||.016);last=t;if(radioTimer>0&&phase==='playing'&&input.locked){radioTimer-=dt;if(radioTimer<=0){$('missionRadio').hidden=true;if(radioQueue.length)announceMission(radioQueue.shift())}}fpsAverage+=(1/dt-fpsAverage)*.035;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').hidden=true}if(world){if(phase==='crashIntro'&&crashIntro){const before=crashIntro.time,pose=crashIntro.update(dt);if(before<CRASH_TIMES.impact&&crashIntro.time>=CRASH_TIMES.impact){audio.aircraft(false);audio.aircraftAlarm(false);audio.noiseSound(1.2,110,.7);audio.noiseSound(.4,2400,.35);audio.crashTrauma()}for(const scrape of [8.16,8.4,8.75,9.1,9.5,10])if(before<scrape&&crashIntro.time>=scrape){audio.noiseSound(.32,700,.15);audio.noiseSound(.2,120,.18)}for(const [burst,x,z]of [[9.9,-4.4,8.4],[11.4,4.4,9]])if(before<burst&&crashIntro.time>=burst)audio.noiseSound(.65,130,.24,{x,y:1,z});for(const [cue,kind]of [[13.6,'breath'],[14.4,'grunt'],[16.25,'grunt'],[18.1,'breath'],[19.9,'grunt'],[21.8,'grunt'],[23.6,'breath'],[25.3,'grunt'],[27.2,'grunt']])if(before<cue&&crashIntro.time>=cue)audio.strain(kind);for(const crawl of [14.4,16.25,18.1,19.9,21.8,23.6,25.3,27.2])if(before<crawl&&crashIntro.time>=crawl)audio.noiseSound(.16,370,.12);$('insertionFade').style.opacity=pose.fade;$('insertionCaption').textContent=crashIntro.caption;$('insertionStage').textContent=pose.view==='exterior'?'EXTERIOR / WRECKAGE':'FIRST PERSON / '+pose.phase.toUpperCase();$('insertionProgress').style.width=crashIntro.time/CRASH_TIMES.end*100+'%';if(pose.finished)finishCrashIntro()}if(phase==='insertion'&&insertion){const before=insertion.time,pose=insertion.update(dt);for(const [cue,frequency,duration,gain]of [[5,220,.55,.13],[8.5,940,.1,.09],[9.2,2600,.08,.19],[9.7,1700,.06,.16],[20.2,2100,.09,.13]])if(before<cue&&insertion.time>=cue){audio.noiseSound(duration,frequency,gain);if(cue===8.5)audio.tone(940,.13,.07)}if(insertion.time>=10&&insertion.time<20&&Math.floor(before*5)!==Math.floor(insertion.time*5))audio.noiseSound(.22,1300,.045);for(const footfall of [5.4,6,6.6,7.2,7.8,8.4,DROP.touchdown+.1])if(before<footfall&&insertion.time>=footfall)audio.step(false);if(before<DROP.ziplineStart&&insertion.time>=DROP.ziplineStart){audio.rotor(false);audio.noiseSound(.35,1600,.16)}$('insertionFade').style.opacity=insertion.time>DROP.handoff?Math.sin(Math.min(1,(insertion.time-DROP.handoff)/2)*Math.PI):0;$('insertionCaption').textContent=insertion.caption;$('insertionStage').textContent=pose.phase==='flyover'?'SHORT APPROACH / RAVEN ONE':pose.phase==='rise'||pose.phase==='walk'?'FIRST PERSON / REAR RAMP':pose.phase==='zipline'?'FIRST PERSON / ZIP LINE':'AIRBORNE / '+pose.phase.toUpperCase();$('insertionProgress').style.width=insertion.time/INSERTION_DURATION*100+'%';$('skipFlightButton').hidden=insertion.time>=DROP.flyoverEnd;if(pose.finished)finishInsertion()}if(phase==='playing'&&player){input.tick(dt,aimTarget());const snap=input.snapshot();if(mode==='online'&&input.locked&&snap.fire&&WEAPONS[player.weapon].auto)predictShot();if(mode==='solo'&&input.locked){accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps++<5){sim.update(1/60,new Map([[player.id,snap]]));accumulator-=1/60}processEvents(sim.drainEvents());view=sim.snapshot();if(sim.finished)results(view)}else if(mode==='online'){if(input.locked)movePlayer(player,snap,dt);lastNetwork+=dt;if(lastNetwork>1/30){network.send('input',{input:input.locked?snap:{x:0,z:0,yaw:input.yaw,pitch:input.pitch},seq:++sequence});lastNetwork=0}nextPing-=dt;if(nextPing<0){network.send('ping',{time:performance.now()});nextPing=2}if(performance.now()-network.lastSnapshot>5000&&network.lastSnapshot)toast('Waiting for the server…',1)}feedbackFrame=damageFeedback.update(dt,player,reducedMotion);let eye=player.y+player.height-.13;world.camera.position.set(player.x,T.MathUtils.damp(world.camera.position.y,eye,22,dt),player.z);const slideRoll=!reducedMotion&&player.slideTime>0?Math.sin((1-player.slideTime/.75)*Math.PI)*.025:0;world.camera.rotation.set(input.pitch,input.yaw,feedbackFrame.roll+slideRoll,'YXZ');const aim=isAiming(snap,player,view?.time||0);let fov=aim?sightFov(settings.fov,player.weapon,input.zoom):settings.fov+(player.slideTime>0?7:player.sprinting&&Math.hypot(player.vx,player.vz)>3?5:0);world.camera.fov=T.MathUtils.damp(world.camera.fov,fov,14,dt);world.camera.updateProjectionMatrix();weapon.update(dt,player,snap,view?.time||0,settings);if(view)world.updateAvatars(view.players,player.id,dt);updateHUD(dt);lastMapUpdate+=dt;if(lastMapUpdate>.2){lastMapUpdate=0;refreshMap()}drawEquipment();stepTimer-=dt;if(input.locked&&player.grounded&&Math.hypot(player.vx,player.vz)>1.4&&stepTimer<=0){audio.step(Math.abs(player.x)<12);stepTimer=player.sprinting?.29:snap.crouch?.65:.43}audio.listener(player)}else if(phase==='menu'){weapon.group.visible=false;let time=t*.00005;world.camera.position.set(4+Math.sin(time*1.7)*3,3.1+Math.sin(time*1.3)*.5,12+Math.cos(time)*26);world.camera.lookAt(-2+Math.sin(time*.9)*4,2.7,Math.cos(time)*26-10);world.camera.fov=settings.fov;world.camera.updateProjectionMatrix()}world.updateSurvival(phase==='playing'?view:null);world.updateMission(phase==='playing'?view:null);world.updateSupplies(phase==='playing'?view:null);world.update(dt);world.render();$('performance').textContent=Math.round(fpsAverage)+' FPS (current rendered scene). Performance varies by GPU and display resolution.'}}
try{world=new World($('viewport'),settings.quality);arenaCovers=new ArenaCovers(world.renderer,()=>world.render());audio=new AudioEngine();audio.setVolume(settings.volume);input=new Input($('viewport'),settings,gameAction);weapon=new WeaponView(world.camera);weapon.group.visible=false;network=new Network(networkMessage,msg=>{toast(msg,8);if(mode==='online'){onlineInsertionPending=false;insertion?.dispose();insertion=null;audio.rotor(false);$('insertionOverlay').hidden=true;phase='menu';mode='menu';player=null;view=null;$('hud').hidden=true;document.exitPointerLock?.();screen('multiplayer');$('networkError').textContent=msg}});updateSettingFields();$('loading').hidden=true;requestAnimationFrame(frame)}catch(e){$('loading').hidden=true;$('fatal').style.display='block';$('fatal').textContent='The 3D renderer could not start. Operation Ghost Town needs a desktop browser with WebGL 2 and hardware acceleration. '+e.message;console.error(e)}
window.addEventListener('keydown',e=>{if(phase==='insertion'&&e.code==='Space'&&!e.repeat){e.preventDefault();if(insertion?.time<DROP.flyoverEnd)insertion.skipFlight();}});
window.addEventListener('error',e=>{console.error('Game runtime error:',e.error);if($('toast'))toast('A runtime error occurred. Reload the page to restart.',8)});

// Pulsebox: ?room=CODE (from the site's Play with friends) opens the multiplayer screen with that code filled in
try{const q=new URLSearchParams(location.search).get('room');if(q&&/^[A-Za-z0-9]{4}$/.test(q)){const go=()=>{if(!$('roomCode')){setTimeout(go,300);return}$('roomCode').value=q.toUpperCase();screen('multiplayer')};setTimeout(go,600)}}catch{}
